package net.karenax.fred;

import android.content.Context;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** Bounded HTTP/1.1 server. Exactly one request per socket, always bound to IPv4 loopback. */
final class LoopbackServer implements AutoCloseable {
    private final Context context;
    final ClientBackend backend;
    private final ServerSocket server;
    private final ThreadPoolExecutor workers=new ThreadPoolExecutor(4,16,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(24));
    private volatile boolean closed;
    private final Set<Socket> sockets=Collections.synchronizedSet(new HashSet<>());
    LoopbackServer(Context context,ClientBackend backend)throws IOException{this.context=context;this.backend=backend;server=new ServerSocket();server.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0),32);Thread accept=new Thread(this::accept,"fred-loopback");accept.start();}
    int port(){return server.getLocalPort();}
    String origin(){return "http://127.0.0.1:"+port();}
    String chatUrl(){return origin()+"/chat/"+backend.bootstrap;}
    private void accept(){while(!closed)try{Socket socket=server.accept();socket.setSoTimeout(30000);sockets.add(socket);try{workers.execute(()->handle(socket));}catch(RejectedExecutionException e){try{reply(socket.getOutputStream(),503,Json.object("error",Json.object("message","Trop de requêtes locales.")));}finally{socket.close();sockets.remove(socket);}}}catch(IOException e){if(closed)return;}}
    private static String line(InputStream input,int max)throws IOException {ByteArrayOutputStream out=new ByteArrayOutputStream();int b;while((b=input.read())!=-1){if(b=='\n'){byte[] raw=out.toByteArray();if(raw.length<1||raw[raw.length-1]!='\r')throw new IOException("Entête invalide.");return new String(raw,0,raw.length-1,StandardCharsets.ISO_8859_1);}if(out.size()>=max)throw new IOException("Entête trop long.");out.write(b);}return null;}
    private void handle(Socket socket){try{InputStream input=new BufferedInputStream(socket.getInputStream());OutputStream output=new BufferedOutputStream(socket.getOutputStream());String request=line(input,2048);if(request==null)return;String[] parts=request.split(" ");if(parts.length!=3||!parts[2].equals("HTTP/1.1")&&!parts[2].equals("HTTP/1.0")){reply(output,400,error("Requête invalide."));return;}String method=parts[0],path=parts[1];Map<String,String> headers=new HashMap<>();int size=0;String next;while((next=line(input,8192))!=null&&!next.isEmpty()){size+=next.length();int colon=next.indexOf(':');if(colon<1||size>32768){reply(output,400,error("Entête invalide."));return;}String name=next.substring(0,colon).toLowerCase(Locale.ROOT),value=next.substring(colon+1).trim();if(headers.put(name,value)!=null){reply(output,400,error("Entête dupliqué."));return;}}
            String host="127.0.0.1:"+port(),origin=headers.get("origin");if(!host.equals(headers.get("host"))||origin!=null&&!origin.equals(origin())){reply(output,403,error("Accès local uniquement."));return;}
            if(method.equals("GET")&&path.equals("/chat/"+backend.bootstrap)){html(output);return;}
            String authorization=headers.get("authorization");if(authorization==null||!MessageDigest.isEqual(authorization.getBytes(StandardCharsets.UTF_8),("Bearer "+backend.key).getBytes(StandardCharsets.UTF_8))){reply(output,401,error("Clé API locale requise."));return;}
            if(method.equals("GET")){if(Arrays.asList("/client/state","/client/history","/client/draft","/client/integrations","/v1/models").contains(path)){reply(output,200,backend.get(path,port()));return;}if(Arrays.asList("/v1/status","/v1/workspace","/v1/notifications","/v1/agent/state").contains(path)){forward(output,path,null,false,headers.get("x-qwen-request"));return;}}
            else if(method.equals("POST")){
                Set<String> local=new HashSet<>(Arrays.asList("/client/endpoint","/client/preferences","/client/history","/client/history/sync","/client/history/restore-ack","/client/history/flush","/client/history/recover","/client/draft","/client/update/check","/client/update/apply"));Set<String> remote=new HashSet<>(Arrays.asList("/v1/embeddings","/v1/chat/completions","/v1/context","/v1/cancel","/v1/workspace/action","/v1/notifications/action","/v1/agent/action"));if(!local.contains(path)&&!remote.contains(path)){reply(output,404,error("Route non disponible."));return;}
                int limit=path.equals("/v1/embeddings")?65536:path.startsWith("/client/history")||path.equals("/v1/chat/completions")||path.equals("/v1/context")?10*1024*1024:path.equals("/v1/workspace/action")?8*1024*1024:2*1024*1024;String length=headers.get("content-length");if(headers.containsKey("transfer-encoding")||length==null||!length.matches("[0-9]{1,9}")||!headers.getOrDefault("content-type","").startsWith("application/json")){reply(output,400,error("Corps JSON attendu."));return;}int count=Integer.parseInt(length);if(count<1||count>limit){reply(output,400,error("Requête trop volumineuse."));return;}byte[] body=new byte[count];int read=0;while(read<count){int n=input.read(body,read,count-read);if(n<0)throw new EOFException();read+=n;}
                // Drain the bounded request first so closing the socket preserves the JSON error.
                if(count>2*1024*1024&&(path.equals("/v1/chat/completions")||path.equals("/v1/context"))&&!Profile.HTTPS.equals(backend.remote.endpoint())){
                    reply(output,413,Json.object("error",Json.object("code","wireguard_payload_too_large","message","Le message et ses pièces jointes dépassent la limite de 2 Mo du tunnel WireGuard. Réduisez les images, retirez des pièces jointes ou commencez une nouvelle conversation.")));return;
                }
                JSONObject values=new JSONObject(new String(body,StandardCharsets.UTF_8));if(local.contains(path))reply(output,200,backend.post(path,values));else forward(output,path,body,values.optBoolean("stream",false),headers.get("x-qwen-request"));return;
            }
            reply(output,404,error("Route non disponible."));
        }catch(Remote.HttpError e){safeReply(socket,e.status,e.body);}catch(HistorySync.Conflict e){safeReply(socket,409,error(e.getMessage()));}catch(IllegalStateException e){safeReply(socket,500,Json.object("error",Json.object("code","history_unreadable","message",e.getMessage())));}catch(Exception e){safeReply(socket,e instanceof IllegalArgumentException||e instanceof JSONException?400:503,error(Remote.safeMessage(e)));}finally{sockets.remove(socket);try{socket.close();}catch(IOException ignored){}}}
    private void safeReply(Socket socket,int code,JSONObject value){try{reply(socket.getOutputStream(),code,value);}catch(IOException ignored){}}
    private void html(OutputStream output)throws Exception {String nonce=Json.token();String content;try(InputStream stream=context.getAssets().open("android-chat.html")){content=new String(SecureStore.readBounded(stream,2*1024*1024),StandardCharsets.UTF_8);}content=content.replace("__CONFIG__",backend.config().toString().replace("<","\\u003c")).replace("__NONCE__",nonce);byte[] bytes=content.getBytes(StandardCharsets.UTF_8);headers(output,200,"text/html; charset=utf-8",bytes.length,"Content-Security-Policy: default-src 'none'; script-src 'nonce-"+nonce+"'; style-src 'nonce-"+nonce+"'; connect-src 'self'; img-src data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\n");output.write(bytes);output.flush();}
    private void forward(OutputStream output,String path,byte[] body,boolean streaming,String requestId)throws Exception {boolean tracked=!path.equals("/v1/cancel"),chatStream=streaming&&path.equals("/v1/chat/completions"),sent=false,done=false,eventStream=false;Remote.Response response=null;if(tracked)backend.remote.active.incrementAndGet();if(chatStream)backend.remote.startStream();try{response=backend.remote.open(path,body,requestId);if(response.status!=200){byte[] raw=SecureStore.readBounded(response.input,65536);JSONObject error;try{error=new JSONObject(new String(raw,StandardCharsets.UTF_8));}catch(JSONException e){error=error("Le serveur a répondu avec une erreur HTTP "+response.status+".");}backend.remote.inspectError(error);reply(output,response.status,error);return;}eventStream=streaming&&response.type!=null&&response.type.toLowerCase(Locale.ROOT).startsWith("text/event-stream");headers(output,200,eventStream?"text/event-stream":"application/json; charset=utf-8",-1,"");output.flush();sent=true;if(eventStream){BufferedReader reader=new BufferedReader(new InputStreamReader(response.input,StandardCharsets.UTF_8));String line;while((line=reader.readLine())!=null){if(line.equals("data: [DONE]"))done=true;if(chatStream)backend.remote.streamLine(line);output.write((line+"\n").getBytes(StandardCharsets.UTF_8));output.flush();}if(!done)throw new IOException("Flux interrompu.");}else{byte[] buffer=new byte[65536];int count;while((count=response.input.read(buffer))!=-1){output.write(buffer,0,count);output.flush();}done=true;}}catch(Exception error){backend.remote.failure("connection_error","Connexion au serveur IA interrompue. Réessayez la requête.");if(!sent){if(error instanceof Remote.HttpError)reply(output,((Remote.HttpError)error).status,((Remote.HttpError)error).body);else reply(output,503,error(Remote.safeMessage(error)));}else if(eventStream){try{output.write(("\n\ndata: "+Json.object("error",Json.object("code","connection_error","message","Connexion interrompue : la réponse peut être incomplète."))+"\n\n").getBytes(StandardCharsets.UTF_8));output.flush();}catch(IOException ignored){}}}finally{if(response!=null)backend.remote.finished(response);if(chatStream)backend.remote.endStream(done);if(tracked)backend.remote.active.decrementAndGet();}}
    private static JSONObject error(String message){return Json.object("error",Json.object("message",message));}
    private static void headers(OutputStream output,int code,String type,int length,String extra)throws IOException {String reason=code==200?"OK":code==400?"Bad Request":code==401?"Unauthorized":code==403?"Forbidden":code==404?"Not Found":code==409?"Conflict":code==413?"Payload Too Large":code==500?"Internal Server Error":"Service Unavailable";String head="HTTP/1.1 "+code+" "+reason+"\r\nContent-Type: "+type+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n"+(length>=0?"Content-Length: "+length+"\r\n":"")+extra+"\r\n";output.write(head.getBytes(StandardCharsets.ISO_8859_1));}
    private static void reply(OutputStream output,int code,JSONObject value)throws IOException {byte[] bytes=Json.bytes(value);headers(output,code,"application/json; charset=utf-8",bytes.length,"");output.write(bytes);output.flush();}
    @Override public void close(){closed=true;try{server.close();}catch(IOException ignored){}for(Socket socket:new ArrayList<>(sockets))try{socket.close();}catch(IOException ignored){}workers.shutdownNow();backend.close();}
}
